package io.github.ssrajadh.prep.data.content

import kotlinx.serialization.Serializable

// Bundled content is read-only and generated by the pipeline (see /pipeline).
// These classes mirror the JSON in app/src/main/assets/content/.
// @Serializable makes the Kotlin compiler plugin generate a parser for each class at build time.

@Serializable
data class Track(val id: String, val name: String, val description: String)

@Serializable
data class Topic(val id: String, val trackId: String, val name: String, val order: Int)

@Serializable
data class KeyPoint(val id: String, val text: String, val group: String? = null)

@Serializable
data class Source(val title: String, val url: String, val section: String)

@Serializable
data class Verified(val status: String, val checkedAt: String? = null)

@Serializable
data class Card(
    val id: String,
    val trackId: String,
    val topicId: String,
    val kind: String,
    val difficulty: Int,
    val prompt: String,
    val keyPoints: List<KeyPoint>,
    val explanation: String,
    val sources: List<Source>,
    val prereqs: List<String> = emptyList(),
    val version: Int,
    val verified: Verified,
) {
    val isDesign: Boolean get() = kind == "design"

    /**
     * Fingerprint of the key points. If it changes between app versions, the card's
     * scheduling is reset (the "answer" changed). Wording changes elsewhere keep progress.
     */
    val keyPointsHash: String
        get() = keyPoints.joinToString("\u0001") { "${it.id}\u0002${it.text}" }.hashCode().toString(16)
}

@Serializable
data class TracksFile(val tracks: List<Track>, val topics: List<Topic>)

@Serializable
data class CardsFile(val cards: List<Card>)

/** Everything bundled in the APK, loaded once. */
data class Content(
    val tracks: List<Track>,
    val topics: List<Topic>,
    val cards: List<Card>,
) {
    val cardsById: Map<String, Card> = cards.associateBy { it.id }
    val topicsById: Map<String, Topic> = topics.associateBy { it.id }
    val tracksById: Map<String, Track> = tracks.associateBy { it.id }

    fun cardsInTrack(trackId: String) = cards.filter { it.trackId == trackId }
    fun topicsInTrack(trackId: String) = topics.filter { it.trackId == trackId }.sortedBy { it.order }
}
